// ratelimit/ratelimit.go
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time so tests can drive it deterministically.
type Clock interface {
	Now() time.Time
}

// RealClock returns the system time.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

// Bucket is a concurrency-safe token-bucket rate limiter.
//
// The bucket holds at most capacity tokens. It is refilled at rate
// tokens per second, up to capacity. AllowN consumes n tokens if and
// only if n tokens are currently available; otherwise it consumes
// nothing and returns false.
type Bucket struct {
	mu       sync.Mutex
	clock    Clock
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
}

// NewBucket validates and returns a Bucket pre-filled with capacity tokens.
//
// capacity must be > 0 and finite. rate must be > 0 and finite.
// clock must be non-nil.
func NewBucket(clock Clock, capacity, rate float64) (*Bucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	if math.IsNaN(capacity) || math.IsInf(capacity, 0) || capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be finite and > 0")
	}
	if math.IsNaN(rate) || math.IsInf(rate, 0) || rate <= 0 {
		return nil, errors.New("ratelimit: rate must be finite and > 0")
	}
	now := clock.Now()
	return &Bucket{
		clock:    clock,
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     now,
	}, nil
}

// AllowN reports whether n tokens can be consumed now.
//
// On success it consumes n tokens; on failure it consumes nothing.
// n must be >= 0; negative n is rejected.
func (b *Bucket) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	b.mu.Lock()
	defer b.mu.Unlock()

	now := b.clock.Now()
	b.tokens = b.refillLocked(now)
	need := float64(n)
	if b.tokens < need {
		return false
	}
	b.tokens -= need
	return true
}

// refillLocked advances the bucket from b.last to now, adding
// rate * elapsed seconds of tokens, capped at capacity.
func (b *Bucket) refillLocked(now time.Time) float64 {
	elapsed := now.Sub(b.last)
	if elapsed > 0 {
		b.tokens += float64(elapsed) * (b.rate / float64(time.Second))
		if b.tokens > b.capacity {
			b.tokens = b.capacity
		}
		b.last = now
	}
	return b.tokens
}
