// ratelimit/ratelimit.go
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time so tests can advance deterministically.
type Clock interface {
	Now() time.Time
}

// RealClock returns the system time.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	clock    Clock
	rate     float64 // tokens per second
	capacity float64
	tokens   float64
	last     time.Time
}

// New validates arguments and returns a Limiter pre-filled to capacity.
func New(clock Clock, rate, capacity float64) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if math.IsNaN(rate) || math.IsInf(rate, 0) || rate <= 0 {
		return nil, errors.New("ratelimit: rate must be a positive finite number")
	}
	if math.IsNaN(capacity) || math.IsInf(capacity, 0) || capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be a positive finite number")
	}
	now := clock.Now()
	return &Limiter{
		clock:    clock,
		rate:     rate,
		capacity: capacity,
		tokens:   capacity,
		last:     now,
	}, nil
}

// AllowN reports whether n tokens may be consumed now. On success it
// atomically deducts n tokens; otherwise the bucket is left unchanged.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	want := float64(n)
	if l.tokens < want {
		return false
	}
	l.tokens -= want
	return true
}

// Tokens returns the current token count (testing/diagnostics helper).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		t := l.tokens + elapsed*l.rate
		if t > l.capacity {
			t = l.capacity
		}
		return t
	}
	return l.tokens
}
