	fc := newFakeClock()
	tests := []struct {
		name     string
		clock    Clock
		rate     float64
		capacity float64
		wantErr  bool
	}{
		{"nil clock", nil, 1, 1, true},
		{"zero rate", fc, 0, 1, true},
		{"negative rate", fc, -1, 1, true},
		{"inf rate", fc, math.Inf(1), 1, true},
		{"nan rate", fc, math.NaN(), 1, true},
		{"zero capacity", fc, 1, 0, true},
		{"negative capacity", fc, 1, -1, true},
