		{"valid", fc, 2.5, 10, false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, err := New(tc.clock, tc.rate, tc.capacity)
			if tc.wantErr {
				if err == nil {
					t.Fatalf("expected error, got nil")
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if l == nil {
				t.Fatal("expected non-nil limiter")
			}
			if got := l.Tokens(); got != tc.capacity {
				t.Fatalf("initial tokens = %v, want %v", got, tc.capacity)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	fc := newFakeClock()
	l, err := New(fc, 1, 3) // 1 token/sec, capacity 3
	if err != nil {
		t.Fatal(err)
	}

	tests := []struct {
		name string
		n    int
		ok   bool
	}{
		{"one token", 1, true},
		{"two tokens", 2, true},
		{"exceeds capacity", 1, false},
		{"zero tokens", 0, true},
		{"negative", -1, false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := l.AllowN(tc.n); got != tc.ok {
				t.Fatalf("AllowN(%d) = %v, want %v", tc.n, got, tc.ok)
			}
		})
	}

	// Bucket is empty; advance 2s -> 2 tokens available.
	fc.Advance(2 * time.Second)
	if !l.AllowN(2) {
		t.Fatal("expected 2 tokens to be available after 2s")
	}
	if l.AllowN(1) {
		t.Fatal("expected bucket to be empty")
	}

	// Advance 1s -> 1 token, but capacity caps at 3.
	fc.Advance(time.Second)
	if !l.AllowN(1) {
		t.Fatal("expected 1 token after 1s")
	}
	// Advance 10s: would be 10 tokens, capped at 3.
	fc.Advance(10 * time.Second)
	if !l.AllowN(3) {
		t.Fatal("expected 3 tokens (capacity cap)")
	}
	if l.AllowN(1) {
		t.Fatal("expected bucket full at capacity")
	}
}

